{"component_id":"component-e8edae998877","code":"def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count integers in [start, finish] ending in s with all digits <= limit."""
    suffix_len = len(s)
    if not s or any(not ch.isdigit() for ch in s) or any(int(ch) > limit for ch in s):
        return 0
    if s[0] == "0":
        # The suffix itself may include zeroes (e.g. "10"), but a full integer
        # cannot have a leading zero when it consists only of the suffix.
        suffix_alone_valid = False
    else:
        suffix_alone_valid = True

    def valid_prefix(prefix: str) -> bool:
        return bool(prefix) and prefix[0] != "0" and all(int(ch) <= limit for ch in prefix)

    def prefixes_less_than(bound: str) -> int:
        """Valid p-digit prefixes lexicographically smaller than bound."""
        p = len(bound)
        total = 0
        for i, char in enumerate(bound):
            lo = 1 if i == 0 else 0
            hi = limit
            digit = int(char)
            choices = max(0, min(hi, digit - 1) - lo + 1)
            remaining = p - i - 1
            total += choices * (limit + 1) ** remaining
            if digit < lo or digit > hi:
                return total
        # The bound itself is not included in the strict count.
        return total

    def count_to(bound: int) -> int:
        if bound < start or bound <= 0:
            return 0
        bound_text = str(bound)
        total = 0
        for length in range(suffix_len, len(bound_text) + 1):
            if length < suffix_len:
                continue
            prefix_len = length - suffix_len
            if length < len(bound_text):
                if prefix_len == 0:
                    if suffix_alone_valid:
                        total += 1
                elif limit >= 1:
                    total += limit * (limit + 1) ** (prefix_len - 1)
                continue

            # The only length equal to the bound's length.
            if prefix_len == 0:
                if suffix_alone_valid and s <= bound_text:
                    total += 1
            else:
                bound_prefix = bound_text[:-suffix_len]
                bound_suffix = bound_text[-suffix_len:]
                total += prefixes_less_than(bound_prefix)
                if valid_prefix(bound_prefix) and s <= bound_suffix:
                    total += 1
        return total

    return count_to(finish) - count_to(start - 1)
